+					if st.mask != nil && !reflect.DeepEqual(origMask, st.mask) {
+						t.Errorf("Netmask was mutated: %q, want %q", origMask, st.mask)
+					}
+
+					if got := st.ip.String(); got != origIP {
+						t.Errorf("IP was mutated: %q, want %q", got, origIP)
+					}
+				})
+			}
+		})
+	}
